import React from 'react';
import Button from '@mui/material/Button';
import Box from '@mui/material/Box';

const PageComponent = ({serverData, movePage}) => {
  return (
    <div className="m-6 flex flex-row justify-center">
    {serverData.prev ?
     <Box m={1} display="inline-block">
       <Button variant="contained" color="primary" size="small"
       onClick={() => movePage({page:serverData.prevPage} )}>
       Prev </Button>
     </Box> : <></>}

     {serverData.pageNumList.map(pageNum =>
     <Box m={1} display="inline-block" key={pageNum}>
       <Button variant="contained" color={serverData.current === pageNum? 'secondary':'primary'} size="small"
       onClick={() => movePage( {page:pageNum})}>
       {pageNum}
       </Button>
     </Box>
      )}
   </div>
  );
}
export default PageComponent;
